import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String status = req.getParameter("status");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        // Basic input normalization
        if (assetType != null) assetType = assetType.replaceAll("[^a-zA-Z0-9_]", "");
        if (status != null) status = status.replaceAll("[^a-zA-Z_]", "");

        // Build query with parameterized WHERE but dynamic ORDER BY
        StringBuilder sql = new StringBuilder(
            "SELECT asset_id, asset_name, owner, status, created_at FROM assets WHERE 1=1");

        if (assetType != null && !assetType.isEmpty()) {
            sql.append(" AND asset_type = ?");
        }
        if (owner != null && !owner.isEmpty()) {
            sql.append(" AND owner = ?");
        }
        if (status != null && !status.isEmpty()) {
            sql.append(" AND status = ?");
        }

        // Dynamic sort - validated against column names
        String[] allowedCols = {"asset_id", "asset_name", "owner", "status", "created_at"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equalsIgnoreCase(sortCol)) {
                    validSort = true;
                    break;
                }
            }
        }
        if (validSort) {
            sql.append(" ORDER BY ").append(sortCol);
            if ("desc".equalsIgnoreCase(sortDir)) {
                sql.append(" DESC");
            } else {
                sql.append(" ASC");
            }
        }

        // Secondary search endpoint for full-text (legacy)
        String freeText = req.getParameter("q");
        if (freeText != null && !freeText.isEmpty()) {
            // NOTE: This was supposed to use FTS but the pg_trgm approach
            // required raw SQL. TODO: migrate to prepared statement.
            sql = new StringBuilder(
                "SELECT asset_id, asset_name, owner, status, created_at FROM assets " +
                "WHERE asset_name ILIKE '%" + freeText + "%' " +
                "OR owner ILIKE '%" + freeText + "%' " +
                "ORDER BY created_at DESC");
            log.info("Free-text search query: " + freeText);
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = (freeText != null && !freeText.isEmpty())
                 ? conn.prepareStatement(sql.toString())
                 : buildParameterized(conn, sql.toString(), assetType, owner, status);
             ResultSet rs = pstmt.executeQuery()) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":").append(rs.getInt(1)).append(",");
                json.append("\"name\":\"").append(escapeJson(rs.getString(2))).append("\",");
                json.append("\"owner\":\"").append(escapeJson(rs.getString(3))).append("\",");
                json.append("\"status\":\"").append(escapeJson(rs.getString(4))).append("\",");
                json.append("\"created\":\"").append(rs.getTimestamp(5)).append("\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private PreparedStatement buildParameterized(Connection conn, String sql,
            String assetType, String owner, String status) throws SQLException {
        PreparedStatement pstmt = conn.prepareStatement(sql);
        int idx = 1;
        if (assetType != null && !assetType.isEmpty()) pstmt.setString(idx++, assetType);
        if (owner != null && !owner.isEmpty()) pstmt.setString(idx++, owner);
        if (status != null && !status.isEmpty()) pstmt.setString(idx++, status);
        return pstmt;
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
